// coverageMonoImage returns a small deterministic one-band pattern, the same on
// every libvips version. The masks, matrices and histograms take an input of
// this shape.
func coverageMonoImage(t *testing.T) *Image {
	t.Helper()
	img, err := NewEye(33, 33, nil)
	if err != nil {
		t.Fatalf("coverageMonoImage: %v", err)
	}
	t.Cleanup(img.Close)
	return img
}

// coverageImage returns the same pattern with two constant bands: an odd square
// is what rot45 requires, and three bands is the smallest input the colour
// operations accept.
func coverageImage(t *testing.T) *Image {
	t.Helper()
	img := coverageMonoImage(t)
	// bandjoin_const promotes to double; casting back keeps the image an integer
	// format, which is what the savers and bit operations require.
	if err := img.BandjoinConst([]float64{128, 128}); err != nil {
		t.Fatalf("coverageImage: bandjoin: %v", err)
	}
	if err := img.Cast(BandFormatUchar, nil); err != nil {
		t.Fatalf("coverageImage: cast: %v", err)
	}
	// A joined image is multiband; label it sRGB so the colour operations see the
	// input they expect. Copy returns a new image rather than mutating this one.
	srgb, err := img.Copy(&CopyOptions{Interpretation: InterpretationSrgb})
	if err != nil {
		t.Fatalf("coverageImage: copy: %v", err)
	}
	t.Cleanup(srgb.Close)
	return srgb
}
